    @foreach (var item in Displaydata)
    {
        &lt;tr&gt;
             &lt;td&gt;@item.EmpId&lt;/td&gt; 
            &lt;td&gt;@item.EmpName&lt;/td&gt;
            &lt;td&gt;@item.Department&lt;/td&gt;
            &lt;td&gt;@item.Salary&lt;/td&gt;
            &lt;td&gt;&lt;button class=&quot;btn-info&quot; @onclick=&quot;(()=&gt;EditRec(item))&quot;&gt;Edit&lt;/button&gt;&lt;/td&gt;
            &lt;td&gt;&lt;button class=&quot;btn-danger&quot; @onclick=&quot;(() =&gt; DeleteEmprec(item))&quot;&gt;Delete&lt;/button&gt;&lt;/td&gt;
        &lt;/tr&gt;
    }
&lt;/table&gt;
@code {
    List&lt;EmpClass&gt; Displaydata;

    EmpClass Objinsert = new EmpClass();

    bool popup = false;

    void Showpopup()
    {

        //code to show popup and clear the boxes. 
        popup = true;
        Objinsert.EmpName = &quot;&quot;;
        Objinsert.Department = &quot;&quot;;
        Objinsert.Salary = 0;

    }
    void Closepopup()
    {
        //code to close popup
        popup = false;
    }
    // Gets the initial table.
    protected override void OnInitialized()
    {

        Displaydata = Service.GetEmployees();
        //Displaydata.Clear();
    }

    void Insertrec()
    {
        //code to insert record
        // Displaydata.Clear();
        var ObjUpdate = false;
        if(Objinsert.EmpId &gt; 0)
        {
            // Displaydata.Clear();

            ObjUpdate = Service.UpdateEmp(Objinsert);
            popup = false;
        }
        else
        {
            // Displaydata.Clear();
            Objinsert.EmpId = 0;

            Service.Addemployee(Objinsert);
        }

        Displaydata = Service.GetEmployees();
       // Displaydata.Clear();

    }
    void EditRec(EmpClass ecobj)
    {
        Objinsert = ecobj;
        popup = true;
    }

    void DeleteEmprec(EmpClass ecobj)
    {
        Service.DeleteEmp(ecobj);
        Displaydata.Clear();
        Displaydata = Service.GetEmployees();
    }
}
